sys.dont_write_bytecode = True
def _secure_engine(d, layers, cipher_loops):
    _b = d.encode('utf-8')
    for _ in range(layers): pass
    for _i in range(cipher_loops, 0, -1):
        if _i % 2 == 1: _b = base64.b64decode(_b)
        else: _b = base64.b85decode(_b)
        if _i % 3 == 1: _b = zlib.decompress(_b)
        elif _i % 3 == 2: _b = bz2.decompress(_b)
        else: _b = lzma.decompress(_b)
    return _b.decode('utf-8')
